// src/pages/Inscripcion.js
import React, { useState } from "react";
import { useParams } from "react-router-dom";

const Inscripcion = () => {
  const { cursoId } = useParams();
  const [formData, setFormData] = useState({
    nombre: "",
    email: "",
    telefono: "",
    edad: "",
    ocupacion: "",
    cursoId
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:3001/api/usuarios/inscribirse", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });

      const data = await response.json();
      if (response.ok) {
        window.location.href = `https://www.paypal.com/checkoutnow?token=${data.paymentId}`;
      } else {
        alert("Error en la inscripción");
      }
    } catch (error) {
      console.error("Error al conectar con el servidor:", error);
    }
  };

  return (
    <div>
      <h2>Inscribirse en el curso</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" name="nombre" placeholder="Nombre" onChange={handleChange} required />
        <input type="email" name="email" placeholder="Email" onChange={handleChange} required />
        <button type="submit">Pagar con PayPal</button>
      </form>
    </div>
  );
};

export default Inscripcion;
